import{_ as d,O as a,H as u,f as h,b as t,j as l,k as r,ac as i,i as s}from"./chunks/framework.Cvt1eIE0.js";const P=JSON.parse('{"title":"一、 基础属性与常驻机制","description":"","frontmatter":{},"headers":[],"relativePath":"mechanics/core.md","filePath":"mechanics/core.md"}'),c={name:"mechanics/core.md"};function b(m,o,p,f,_,q){const e=a("Infobox"),n=a("DST"),g=a("MediaCard");return u(),h("div",null,[o[11]||(o[11]=t("h1",{id:"一、-基础属性与常驻机制",tabindex:"-1"},[l("一、 基础属性与常驻机制 "),t("a",{class:"header-anchor",href:"#一、-基础属性与常驻机制","aria-label":'Permalink to "一、 基础属性与常驻机制"'},"​")],-1)),r(e,{title:"芒伊木 (本体)",image:"/mem_card.png",stats:[{label:"生命值",value:"75",icon:"/health_icon.png"},{label:"理智值",value:"200",icon:"/sanity_icon.png"},{label:"饱食度",value:"150",icon:"/hunger_icon.png"},{label:"灵魂值",value:"150",icon:"/soul_icon.png"}],details:[{label:"初始物品",value:"封印项圈Lv1"},{label:"基础攻倍",value:"0.5"}]}),o[12]||(o[12]=t("p",null,[l("在原版/类原版环境（永不妥协/永恒新界）下，芒伊木被定位为一名"),t("strong",null,"样样会但样样不精"),l("的全能弱女子。尽管拥有许多花哨的机制，但其机体性能依然贴合原版，部分情况下甚至弱于原版人物。")],-1)),o[13]||(o[13]=t("h2",{id:"基础数值系统",tabindex:"-1"},[l("基础数值系统 "),t("a",{class:"header-anchor",href:"#基础数值系统","aria-label":'Permalink to "基础数值系统"'},"​")],-1)),t("p",null,[o[4]||(o[4]=l("默认三维：",-1)),r(n,{icon:"health"},{default:i(()=>[...o[0]||(o[0]=[l("生命值 (75)",-1)])]),_:1}),o[5]||(o[5]=l("、",-1)),r(n,{icon:"sanity"},{default:i(()=>[...o[1]||(o[1]=[l("理智值 (200)",-1)])]),_:1}),o[6]||(o[6]=l("、",-1)),r(n,{icon:"hunger"},{default:i(()=>[...o[2]||(o[2]=[l("饱食度 (150)",-1)])]),_:1}),o[7]||(o[7]=l("、",-1)),r(n,{icon:"soul"},{default:i(()=>[...o[3]||(o[3]=[l("灵魂值 (150)",-1)])]),_:1}),o[8]||(o[8]=l("。（",-1)),o[9]||(o[9]=t("em",null,"注：以上数值均可在模组设置中调整",-1)),o[10]||(o[10]=l("）",-1))]),o[14]||(o[14]=s('<h3 id="灵魂值系统" tabindex="-1">灵魂值系统 <a class="header-anchor" href="#灵魂值系统" aria-label="Permalink to &quot;灵魂值系统&quot;">​</a></h3><p>芒伊木独有的一种属性，可以通过料理、技能或溢出的治疗恢复。</p><ul><li><strong>溢出治疗</strong>：当血量为满时，溢出的治疗量的 15% 将汇入 <strong>[灵魂池]</strong>。</li><li><strong>缓慢汲取</strong>：[灵魂池]中积蓄的灵魂值将缓慢恢复到实际的 [灵魂值] 当中。积蓄得越多，恢复速度越快（当积蓄 30~40 点时，恢复速度约为 1点/秒）。</li><li><strong>生命维持</strong>：脱战后，每秒将消耗 2 [灵魂值] 恢复 1 生命值。</li></ul><h3 id="暗影亲和与畏惧黑暗" tabindex="-1">暗影亲和与畏惧黑暗 <a class="header-anchor" href="#暗影亲和与畏惧黑暗" aria-label="Permalink to &quot;暗影亲和与畏惧黑暗&quot;">​</a></h3><ul><li><strong>暗影亲和</strong>：自带暗影亲和（原版环境中可看到墨荒等生物真名，听见暗影收割者说话）。</li><li><strong>暗影反噬</strong>：理智值低于 50% 时，每隔 15~30 秒，有 40% 的概率 <strong>嘲讽</strong> 20 码内（约 3/5 个屏幕）的生物；每次判定还有 10% 的概率在芒伊木附近生成 <strong>[潜伏恐惧]</strong>。</li><li><strong>畏惧黑暗</strong>：进入<strong>夜晚或者洞穴</strong>时，会持续增长压力值。压力值达到一定程度时，若世界未被 [位面封锁] 且处于完全黑暗中，会产生 <strong>幻听/幻觉</strong>。</li></ul><hr><h2 id="已死之人-死亡与复活" tabindex="-1">已死之人：死亡与复活 <a class="header-anchor" href="#已死之人-死亡与复活" aria-label="Permalink to &quot;已死之人：死亡与复活&quot;">​</a></h2><p>芒伊木死亡后不会变成白骨，而是留下 <strong>[芒芒的尸体]</strong>。你可以随时作祟该尸体复活。</p><h3 id="鬼魂特质与机制" tabindex="-1">鬼魂特质与机制 <a class="header-anchor" href="#鬼魂特质与机制" aria-label="Permalink to &quot;鬼魂特质与机制&quot;">​</a></h3><ul><li><strong>鬼魂强化</strong>：鬼魂状态下获得 +200% 移动速度，且可以探开未查明的地图区域。</li><li><strong>死亡转换</strong>：死亡时，剩余的 <code>生命值</code> 将转换为 [灵魂值]，转换比例根据溢出治疗转换率决定。</li><li><strong>作祟复活</strong>：作祟 [芒芒的尸体] 复活时，全额继承死亡时的 [灵魂值]。<code>理智值</code> 与 <code>饱食度</code> 将按照尸体腐烂程度、防腐改造等因素按比例继承（所有复活手段最低保留 25% 三维）。</li><li><strong>面具生物联动</strong>：若被佩戴有 <code>暗域先驱</code> 面具的生物击杀，尸体将转化为官方的 <code>被附身的尸体</code>。作祟夺舍其复活等同于作祟 [芒芒的尸体]，夺舍概率 40%。</li></ul><h3 id="死亡复活惩罚" tabindex="-1">死亡复活惩罚 <a class="header-anchor" href="#死亡复活惩罚" aria-label="Permalink to &quot;死亡复活惩罚&quot;">​</a></h3><p>由于可以随时复活，为平衡强度，复活伴随严厉惩罚：</p><ol><li><strong>复生虚弱</strong>：任意复活后附加<strong>永久</strong>负面状态（只能被特殊手段清除）。持续期间无法恢复灵魂值，-20% 移速，每层 -25% 工作效率，每层每2秒扣除 1% 血量。</li><li><strong>灵魂震荡</strong>：根据死亡与复活点的距离，产生不同程度的惩罚。持续期间无法恢复灵魂值，且受到 1%~225% 的上限惩罚。</li><li><strong>灵魂裂痕</strong>：每次复活失去 25% 灵魂值上限。之后吸收的灵魂值会以 1:1 优先修补该裂痕。</li></ol><h3 id="死亡与复活相关技能" tabindex="-1">死亡与复活相关技能 <a class="header-anchor" href="#死亡与复活相关技能" aria-label="Permalink to &quot;死亡与复活相关技能&quot;">​</a></h3><ul><li><strong>主动求死</strong>：活着时可按 <code>C</code> 键主动死亡，且物品不会掉落。以此方式复活<strong>不会携带</strong> [复生虚弱]。</li><li><strong>死亡回归</strong>：鬼魂状态按 <code>X</code> 键进入 10 秒的死亡回归状态。期间复活不携带 [复生虚弱]，附加 [再一次的机会] 增益，且三维恢复比例额外增加 25%。默认冷却 7 天。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>再一次的机会</strong> (增益)：10秒内极大缩减遇敌感知范围（仅5码）；获得自动拾取/穿戴；30秒内发光、+30%移速、嘲讽特性失效。</p></div><hr><h2 id="三重形态研究" tabindex="-1">三重形态研究 <a class="header-anchor" href="#三重形态研究" aria-label="Permalink to &quot;三重形态研究&quot;">​</a></h2><p>芒伊木拥有三重身份形态：常态为 <strong>人类</strong>；按下 <code>V</code> 键进入 <strong>兽化 (狐狸)</strong>；脱下 [封印项圈] 进入 <strong>怨灵</strong>。兽化与怨灵状态可共存。</p>',19)),r(g,{src:"/mem_model.png",caption:"芒伊木：不同形态拥有完全不同的数值表现",width:"320px"}),o[15]||(o[15]=s('<h3 id="_1-人类形态" tabindex="-1">1. 人类形态 <a class="header-anchor" href="#_1-人类形态" aria-label="Permalink to &quot;1. 人类形态&quot;">​</a></h3><ul><li><strong>数值</strong>：0.5 攻击倍率。</li><li><strong>评价</strong>：无任何特殊机制，最虚弱但最稳定的探索状态。</li></ul><h3 id="_2-兽化形态-狐狸" tabindex="-1">2. 兽化形态 (狐狸) <a class="header-anchor" href="#_2-兽化形态-狐狸" aria-label="Permalink to &quot;2. 兽化形态 (狐狸)&quot;">​</a></h3><ul><li><strong>转换消耗</strong>：进入扣除 20% 饱食度；退出扣除 20% 理智值。</li><li><strong>数值强化</strong>： <ul><li>1.0 攻击倍率，空手伤害 30，且空手攻速大幅提升（极限攻速 2.5~3.75）。</li><li>+35% 移动速度。</li><li>+65% 减伤倍率；+50% 防水，+120 保暖，-90% 潮湿下降。</li><li>自然饱食度消耗翻倍，+3/60 理智光环。会被猪人等视为怪物。</li></ul></li><li><strong>形态代价</strong>：无法佩戴手部装备和绝大部分身体/头部遮耳装备（护甲防御归零但保留特效）。食物收益<strong>减半</strong>，但<strong>免疫食物负面影响</strong>。</li><li><strong>专属技能 - 跳跃 (<code>R</code> 键)</strong>：根据移速决定跳跃距离，可跨越地形且期间霸体。</li><li><strong>专属技能 - 捕猎 (<code>X</code> 键)</strong>：空手捕捉小动物、飞虫。基础成功率 50%。该姿态下 -60% 移速，但有 40% 概率让敌人无法察觉。</li><li><strong>藏食物</strong>：右键地面可挖坑埋藏食物（具有 75% 盐盒级保鲜），仅自己可取出。</li></ul><h3 id="_3-怨灵形态" tabindex="-1">3. 怨灵形态 <a class="header-anchor" href="#_3-怨灵形态" aria-label="Permalink to &quot;3. 怨灵形态&quot;">​</a></h3><ul><li><strong>转换消耗</strong>：脱下项圈立即扣除 20% 生命值（不会致死）。</li><li><strong>数值变化</strong>： <ul><li>攻击力随理智降低而提升，0 理智时达到 1.5 倍攻倍。</li><li>受伤倍率同理，0 理智时承受 1.5 倍伤害。</li><li>-60/60 理智值光环，被视为怪物。</li></ul></li><li><strong>专属技能 - 战斗治愈</strong>：每次命中敌人，消耗 1 点灵魂值恢复 1 点生命值。若灵魂不足则消耗双倍精神值；若皆不足则扣除 1 生命值（可致死）。</li><li><strong>暗影观察者</strong>：理智低于 60% 会出现类似织影者的精神控制视效（不具控制力），佩戴启迪之冠等可免疫。</li></ul><h3 id="形态联动与通用能力" tabindex="-1">形态联动与通用能力 <a class="header-anchor" href="#形态联动与通用能力" aria-label="Permalink to &quot;形态联动与通用能力&quot;">​</a></h3><ul><li><strong>兽化+怨灵</strong>：同时处于双状态时，空手攻击每次附加 10 点位面伤害。</li><li><strong>发射鬼火</strong>：空手（非捕猎姿态）可消耗 3 灵魂值发射 1 颗自动追踪的鬼火，造成 10 点伤害。若具弹射/光照升级，将带来连环打击与视野支持。</li></ul>',8))])}const k=d(c,[["render",b]]);export{P as __pageData,k as default};
